27	class ResumeDriver
28	{
29	public:
30	  // data0/data1/abstractcs/command are defined once in abstract_command.hpp;
31	  // dmcontrol/dmstatus are run-control registers specific to this driver.
32	  static constexpr uint8_t kData0      = kDmiData0;
33	  static constexpr uint8_t kData1      = kDmiData1;
34	  static constexpr uint8_t kDmcontrol  = 0x10;
35	  static constexpr uint8_t kDmstatus   = 0x11;
36	  static constexpr uint8_t kAbstractcs = kDmiAbstractcs;
37	  static constexpr uint8_t kCommand    = kDmiCommand;
38	
39	  static constexpr uint16_t kCsrDpc      = 0x7B1;
40	  static constexpr uint16_t kCsrDcsr     = 0x7B0;
41	  static constexpr uint16_t kCsrPmpcfg0  = 0x3A0;
42	  static constexpr uint16_t kCsrPmpaddr0 = 0x3B0;
43	  static constexpr uint16_t kCsrFcsr     = 0x003;
44	  static constexpr uint16_t kCsrMstatus  = 0x300;
45	  static constexpr uint16_t kCsrMisa     = 0x301;
46	  static constexpr uint16_t kCsrMedeleg  = 0x302;
47	  static constexpr uint16_t kCsrMideleg  = 0x303;
48	  static constexpr uint16_t kCsrMie      = 0x304;
49	  static constexpr uint16_t kCsrMtvec    = 0x305;
50	  static constexpr uint16_t kCsrMscratch = 0x340;
51	  static constexpr uint16_t kCsrMepc     = 0x341;
52	  static constexpr uint16_t kCsrMcause   = 0x342;
53	  static constexpr uint16_t kCsrMtval    = 0x343;
54	  static constexpr uint16_t kCsrMip      = 0x344;
55	  static constexpr uint16_t kCsrSatp     = 0x180;
56	  static constexpr uint16_t kCsrMcycle   = 0xB00;
57	  static constexpr uint16_t kCsrMinstret = 0xB02;
58	  // Andes machine setup CSRs crt0 writes at boot (see hybrid_state_v1):
59	  // mcache_ctl enables the L1 I/D caches, mmisc_ctl holds misc machine config.
60	  static constexpr uint16_t kCsrMcacheCtl = 0x7CA;
61	  static constexpr uint16_t kCsrMmiscCtl  = 0x7D0;
62	  static constexpr uint16_t kCsrVlenb    = 0xC22;
63	  static constexpr uint16_t kCsrVstart   = 0x008;
64	  static constexpr uint16_t kCsrVxsat    = 0x009;
65	  static constexpr uint16_t kCsrVxrm     = 0x00A;
66	  static constexpr uint16_t kCsrVcsr     = 0x00F;
67	  static constexpr uint16_t kCsrVtype    = 0xC21;
68	  static constexpr uint16_t kCsrVl       = 0xC20;
69	
70	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
71	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
72	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
73	
74	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
75	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
76	
77	  static constexpr uint32_t kAbstractcsBusy        = hybrid::kAbstractcsBusy;
78	  static constexpr uint32_t kAbstractcsCmderrMask  = hybrid::kAbstractcsCmderrMask;
79	
80	  // mstatus extension-state fields: FS (bits 14:13), VS (bits 10:9).
81	  // "Initial" (01) is the minimal enable the abstract FPR / V writes require.
82	  static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
83	  static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
84	  static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
85	  static constexpr uint64_t kMstatusVsInitial = 0x200ULL;
86	
87	  static constexpr unsigned kPollIterations = kDmiPollIterations;
88	
89	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
90	  // v_scratch_gpa(ram_base, ram_size) = the mmap's top page). Defaults to the
91	  // "unset" sentinel; a non-V resume never reads it, but a V resume with the
92	  // GPA still unset throws in the sweep (no silent transport via a bogus
93	  // address). The simulator passes the real value from platform.main_memory.
94	  explicit ResumeDriver(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset)
95	      : bus_{bus}, scratch_gpa_{scratch_gpa}
96	  {}
97	
98	  // Halt the hart and wait for it to enter debug mode. dmactive must transition
99	  // 0->1 in its own write before any other DMCONTROL bit is honored (RISC-V
100	  // Debug Spec); then haltreq, then poll allhalted. Shared by resume() and the
101	  // -S startup halt (Simulator::halt_for_debug).
102	  void halt()
103	  {
104	    bus_.write(kDmcontrol, kDmcontrolDmactive);
105	    request_halt();
106	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
107	  }
108	
109	  void resume(const hybrid_state_v1& state)
110	  {
111	    if (state.magic != HYBRID_STATE_MAGIC)
112	      throw std::runtime_error("ResumeDriver::resume: bad magic");
113	    if (state.version != HYBRID_STATE_VERSION)
114	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
115	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
116	    if (state.priv == 2 || state.priv > 3)
117	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
118	
119	    halt();
120	
121	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
122	    // accepted (FS or VS == Off disables the extension and the hart NACKs
123	    // the writes). The drained state.mstatus may legitimately carry FS or
124	    // VS at Off (e.g. an OS context-switched the regs away before the
125	    // trigger fired) -- gating the write on the drained field skips the
126	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
127	    // write mstatus when either extension is in scope; force-OR Initial
128	    // when the drained field is Off. This enable is local to the vsim
129	    // phase; the state.mstatus written to the handoff file is left
130	    // unmodified.
131	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
132	      uint64_t enable_mstatus = state.mstatus;
133	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
134	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
135	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
136	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
137	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
138	    }
139	
140	    // FPR restore (requires mstatus.FS enabled above).
141	    if (state.flags & HYBRID_FLAG_FP) {
142	      for (uint16_t i = 0; i < 32; ++i)
143	        write_64bit_register(regno_fpr(i), state.fpr[i]);
144	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
145	      // fallback scratch x5 is overwritten by the GPR loop below.
146	      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
147	    }
148	
149	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
150	    // the GPR loop overwrites x5 afterward so state is preserved).
151	    if (state.flags & HYBRID_FLAG_V) {
152	      // V data regfile: reload v0..v31 from the shared scratch region via the
153	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
154	      // because the sweep's own vsetvl (e8/m1) clobbers vtype/vl/vstart, which
155	      // the restore then overwrites with the architectural values. The sweep
156	      // uses x5/x6/x7 as scratch (x7 is the base pointer); the GPR loop below
157	      // restores all three. The wire format reserves HYBRID_VLEN_BYTES_MAX per
158	      // register, so that -- not the runtime vlenb -- is the scratch stride.
159	      if (scratch_gpa_ == kVScratchGpaUnset)
160	        throw std::runtime_error(
161	          "ResumeDriver::resume: V state present but scratch GPA unset");
162	      pb_v_data_sweep(bus_, scratch_gpa_, HYBRID_VLEN_BYTES_MAX, state.vlenb,
163	                      /*load=*/true);
164	
165	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
166	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
167	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
168	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
169	      write_64bit_register(regno_gpr(5), state.vl);
170	      write_64bit_register(regno_gpr(6), state.vtype);
171	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
172	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
173	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0.
174	      write_csr_abstract_or_pb(kCsrVstart, state.vstart);
175	      write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
176	      write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
177	      write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
178	    }
179	
180	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
181	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
182	    // in the drained privilege; M-mode states skip the write (prv already 3).
183	    // Before the GPR loop: a PB fallback would clobber scratch x5.
184	    if (state.priv != 3) {
185	      // L2 slice: with PMP implemented and no matching entry, every S/U
186	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
187	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
188	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
189	      // RV64. Tolerant writes: entries beyond what the hart implements
190	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
191	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
192	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
193	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
194	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
195	
196	      const uint64_t dcsr =
197	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
198	      write_csr_abstract_or_pb(kCsrDcsr,
199	                               (dcsr & ~uint64_t{0x3}) | state.priv);
200	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
201	      // silently measure the ROI in the wrong privilege. Verify and abort.
202	      const uint64_t got =
203	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
204	        & 0x3u;
205	      if (got != state.priv)
206	        throw std::runtime_error(
207	          "ResumeDriver::resume: engine does not implement privilege level "
208	          + std::to_string(state.priv)
209	          + " (dcsr.prv pinned to " + std::to_string(got)
210	          + "); pick an S/U-capable engine");
211	    }
212	
213	    // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite).
214	    for (uint16_t i = 1; i < 32; ++i)
215	      write_64bit_register(regno_gpr(i), state.gpr[i]);
216	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
217	
218	    write_csr_tolerant(kCsrMtvec, state.mtvec);
219	
220	    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
221	    // register with no hardware side effects, legal to use inside a trap-free
222	    // ROI. Restore it so a value stashed before the handoff survives into the
223	    // vsim phase.
224	    write_csr_tolerant(kCsrMscratch, state.mscratch);
225	
226	    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
227	    // interrupt-free ROI envelope these are ordinary read/write registers, so a
228	    // value stashed before the handoff must survive into the vsim phase (same
229	    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
230	    // hardware-driven pending bits, or mtval on a core that hardwires it)
231	    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
232	    // S-mode CSRs the M-only default engine does not implement (L3/L4).
233	    write_csr_tolerant(kCsrMepc,   state.mepc);
234	    write_csr_tolerant(kCsrMcause, state.mcause);
235	    write_csr_tolerant(kCsrMtval,  state.mtval);
236	    write_csr_tolerant(kCsrMie,    state.mie);
237	    write_csr_tolerant(kCsrMip,    state.mip);
238	
239	    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
240	    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
241	    // caches) but has no cache model, so without this the cycle engine resumes
242	    // at the ROI with caches at their reset default -- DISABLED -- and the
243	    // whole measured window runs uncached, inflating it severalfold. Tolerant
244	    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
245	    // write as a no-op, and a drained 0 (caches were off) restores the reset
246	    // state, so this is always safe to issue.
247	    write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl);
248	    write_csr_tolerant(kCsrMmiscCtl,  state.mmisc_ctl);
249	
250	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
251	    // from QEMU1's drain value. Without this, vsim's local counter starts
252	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
253	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
254	    // overwrite here as the GPR loop already ran.
255	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
256	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
257	
258	    clear_cmderr_if_set();
259	    request_resume();
260	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
261	                   "ResumeDriver resume");
262	  }
263	
264	private:
265	  void request_halt()
266	  {
267	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
268	  }
269	
270	  void request_resume()
271	  {
272	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
273	  }
274	
275	  void write_64bit_register(uint16_t regno, uint64_t value)
276	  {
277	    write_register_abstract(bus_, regno, value);
278	  }
279	
280	  // Abstract-first CSR write with Program Buffer fallback.
281	  // Tries an abstract register write; if the DM signals cmderr, clears it,
282	  // stages the value in scratch_gpr via abstract GPR write, then executes a
283	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
284	  // to x5 (t0) which the GPR restore loop overwrites later.
285	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
286	                                 uint8_t scratch_gpr = 5)
287	  {
288	    write_64bit_register(regno_csr(csr), value);
289	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
290	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
291	    write_64bit_register(regno_gpr(scratch_gpr), value);
292	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
293	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
294	  }
295	
296	  // Write a CSR-addressable register and clear any cmderr the DM raised.
297	  // Used for CSRs whose abstract-access support may be implementation
298	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
299	  // remaining writes.
300	  void write_csr_tolerant(uint16_t csr, uint64_t value)
301	  {
302	    write_64bit_register(regno_csr(csr), value);
303	    clear_cmderr_if_set();
304	  }
305	
306	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
307	  // is rejected until the bits are W1C-cleared. We tolerate per-register
308	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
309	  // error before resuming so the hart isn't left in a stuck state.
310	  // B17: record the last observed non-zero cmderr and a clear count so a
311	  // partially-broken restore is observable via the public accessors
312	  // instead of silently swallowed.
313	  void clear_cmderr_if_set()
314	  {
315	    const auto status = bus_.read(kAbstractcs);
316	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
317	    if (code != 0u) {
318	      last_observed_cmderr_ = code;
319	      ++cmderr_clear_count_;
320	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
321	    }
322	  }
323	
324	  DmiBus& bus_;
325	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
326	  uint32_t last_observed_cmderr_ = 0;
327	  uint64_t cmderr_clear_count_   = 0;
328	
329	public:
330	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
331	  // at least one abstract write tripped a sticky cmderr the restore
332	  // tolerated by clearing. cmderr_clear_count() is the total number of
333	  // such clears across all calls into clear_cmderr_if_set() this run.
334	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
335	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
336	};
337	
338	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
339	// via an Abstract Command. Halts-and-reads contract: caller must have the
340	// hart in the halted state. Shared by StateDrain (drain at exit), and by
341	// MeasureStartSnapshot (snapshot at K-th retire). If abstractcs.cmderr
342	// goes sticky after the command, the helper clears it and reports 0
343	// rather than blocking the caller -- a missing CSR mirrors as zero
344	// instead of corrupting the adjacent field.
345	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
346	                                     const char* poll_label
347	                                       = "read_register_64")
348	  -> std::optional<uint64_t>
349	{
350	  using RD = ResumeDriver;
351	  bus.write(RD::kCommand,
352	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
353	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
354	  const auto status = bus.read(RD::kAbstractcs);
355	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
356	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
357	    return std::nullopt;
358	  }
359	  const uint64_t lo = bus.read(RD::kData0);
360	  const uint64_t hi = bus.read(RD::kData1);
361	  return lo | (hi << 32);
362	}
363	
364	inline auto read_register_64(DmiBus& bus, uint16_t regno,
365	                             const char* poll_label = "read_register_64")
366	  -> uint64_t
367	{
368	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
369	}
