237	private:
238	  // misa extension letters used by the drain_full flag probe.
239	  static constexpr uint64_t kMisaD = 1ULL << 3;
240	  static constexpr uint64_t kMisaF = 1ULL << 5;
241	  static constexpr uint64_t kMisaV = 1ULL << 21;
242	
243	  // V data dump sweep: vse8.v v0..v31 from the regfile into the scratch page.
244	  // L26: guards on the configured scratch GPA so a V drain never stores to a
245	  // bogus address (mirror of ResumeDriver's reload-sweep guard).
246	  void dump_v_to_scratch(uint64_t vlenb)
247	  {
248	    if (scratch_gpa_ == kVScratchGpaUnset)
249	      throw std::runtime_error(
250	        "StateDrain: V state present but scratch GPA unset");
251	    pb_v_data_sweep(bus_, scratch_gpa_, HYBRID_VLEN_BYTES_MAX, vlenb,
252	                    /*load=*/false);
253	  }
254	
255	  // Undo the dump sweep's clobbers -- vtype/vl/vstart and the x5/x6/x7
256	  // scratch -- from the freshly drained values, so the hart can continue.
257	  void undo_v_sweep_clobbers(const hybrid_state_v1& state)
258	  {
259	    // vtype+vl atomically via vsetvl (direct vtype write sets vill; vl is
260	    // read-only), staged in x5/x6 like the ResumeDriver Tier-B restore.
261	    write_register_abstract(bus_, regno_gpr(5), state.vl);
262	    write_register_abstract(bus_, regno_gpr(6), state.vtype);
263	    const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
264	    exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
265	    // vstart AFTER vsetvl (vsetvl zeroes it), via PB csrrw staged in x7 --
266	    // still scratch until the GPR rewrite below.
267	    write_register_abstract(bus_, regno_gpr(7), state.vstart);
268	    const std::array<uint32_t, 1> pb_vstart = {
269	      encode_csrrw(0, RD::kCsrVstart, 7) };
270	    exec_progbuf(bus_, std::span<const uint32_t>{pb_vstart});
271	    // Scratch GPRs back to the drained architectural values.
272	    write_register_abstract(bus_, regno_gpr(5), state.gpr[5]);
273	    write_register_abstract(bus_, regno_gpr(6), state.gpr[6]);
274	    write_register_abstract(bus_, regno_gpr(7), state.gpr[7]);
275	  }
276	
277	  // Abstract CSR write that clears a sticky cmderr instead of blocking the
278	  // remaining drain (mirror of ResumeDriver::write_csr_tolerant).
279	  void write_csr_tolerant(uint16_t csr, uint64_t value)
280	  {
281	    write_register_abstract(bus_, regno_csr(csr), value);
282	    if ((bus_.read(RD::kAbstractcs) & RD::kAbstractcsCmderrMask) != 0u)
283	      bus_.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
284	  }
285	
286	  DmiBus& bus_;
287	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
288	  uint64_t warmup_mcycle_   = 0;  // F16: zero when warmup boundary never fired
289	  uint64_t warmup_minstret_ = 0;
290	};
