684	static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
685	{
686	    (void) id;
687	    size_t n = qemu_plugin_tb_n_insns(tb);
688	
689	    // BBV-mode: assign a stable bb_id to this TB (1-based, hashed by
690	    // TB-start vaddr). Same id is shared by every insn in the TB.
691	    uint64_t bb_id = 0;
692	    if (bbv_mode && n > 0) {
693	        uint64_t tb_pc = qemu_plugin_insn_vaddr(qemu_plugin_tb_get_insn(tb, 0));
694	        bb_id = bbv_emit_assign_id(bbv_emit, tb_pc);
695	    }
696	
697	    for (size_t i = 0; i < n; i++) {
698	        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);
699	
700	        // Oracle exit-drain mode: exclusive with every other mode (enforced
701	        // at install), so it owns the insn's registration outright. The site
702	        // carries the marker kind so the tick can arm on the EXIT marker.
703	        if (exit_marker_mode || exit_pc_mode) {
704	            HandoffSite *site = g_new0(HandoffSite, 1);
705	            site->kind  = HYBRID_HANDOFF_NONE;
706	            site->vaddr = qemu_plugin_insn_vaddr(insn);
707	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
708	            if (exit_marker_mode && site->size == 4) {
709	                uint32_t raw = 0;
710	                if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) == sizeof(raw))
711	                    hybrid_match_handoff_insn(raw, &site->kind);
712	            }
713	            qemu_plugin_register_vcpu_insn_exec_cb(
714	                insn, on_oracle_tick, QEMU_PLUGIN_CB_R_REGS, site);
715	            continue;
716	        }
717	
718	        // Cosim oracle mode: exclusive with every other mode (enforced at
719	        // install). Same site shape as the exit oracle; kind carries the
720	        // marker match so the tick can arm on the ENTER marker.
721	        if (cosim_marker_mode || cosim_pc_mode) {
722	            HandoffSite *site = g_new0(HandoffSite, 1);
723	            site->kind  = HYBRID_HANDOFF_NONE;
724	            site->vaddr = qemu_plugin_insn_vaddr(insn);
725	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
726	            if (cosim_marker_mode && site->size == 4) {
727	                uint32_t raw = 0;
728	                if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) == sizeof(raw))
729	                    hybrid_match_handoff_insn(raw, &site->kind);
730	            }
731	            qemu_plugin_register_vcpu_insn_exec_cb(
732	                insn, on_cosim_tick, QEMU_PLUGIN_CB_R_REGS, site);
733	            continue;
734	        }
735	
736	        // Lock-step oracle mode: exclusive with every other mode (enforced
737	        // at install). Every insn ticks; the tick arms at lockstep_pc.
738	        if (lockstep_pc_mode) {
739	            HandoffSite *site = g_new0(HandoffSite, 1);
740	            site->kind  = HYBRID_HANDOFF_NONE;
741	            site->vaddr = qemu_plugin_insn_vaddr(insn);
742	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
743	            qemu_plugin_register_vcpu_insn_exec_cb(
744	                insn, on_lockstep_tick, QEMU_PLUGIN_CB_R_REGS, site);
745	            continue;
746	        }
747	
748	        // F14 count tick: registered FIRST so the count is incremented
749	        // before any trigger callback can call exit(200). NO_REGS keeps
750	        // the per-insn cost minimal (a single uint64 add).
751	        if (drain_at_exit_mode) {
752	            qemu_plugin_register_vcpu_insn_exec_cb(
753	                insn, on_count_tick, QEMU_PLUGIN_CB_NO_REGS, NULL);
754	        }
755	
756	        // BBV callback is registered BEFORE icount so that if both modes
757	        // fire on the same insn (icount target == slice multiple), the
758	        // slice row is emitted before exit(200) is called.
759	        if (bbv_mode) {
760	            qemu_plugin_register_vcpu_insn_exec_cb(
761	                insn, on_bbv_tick, QEMU_PLUGIN_CB_NO_REGS,
762	                GUINT_TO_POINTER((guint) bb_id));
763	        }
764	
765	        // Slice-consume callback (F11). Registered after BBV so a BBV
766	        // row at the same boundary is flushed first; ordering vs icount
767	        // is irrelevant (both drain).
768	        if (slice_consume_mode) {
769	            HandoffSite *site = g_new0(HandoffSite, 1);
770	            site->kind  = HYBRID_HANDOFF_ENTER;
771	            site->vaddr = qemu_plugin_insn_vaddr(insn);
772	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
773	            qemu_plugin_register_vcpu_insn_exec_cb(
774	                insn, on_slice_consume_tick, QEMU_PLUGIN_CB_R_REGS, site);
775	        }
776	
777	        if (icount_mode) {
778	            HandoffSite *site = g_new0(HandoffSite, 1);
779	            site->kind  = HYBRID_HANDOFF_ENTER;
780	            site->vaddr = qemu_plugin_insn_vaddr(insn);
781	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
782	            qemu_plugin_register_vcpu_insn_exec_cb(
783	                insn, on_icount_tick, QEMU_PLUGIN_CB_R_REGS, site);
784	        }
785	
786	        if (pc_mode) {
787	            // PC-trigger mode: vaddr-only match; the drain resumes AT the
788	            // boundary (on_handoff_boundary), so the insn size is recorded
789	            // only for completeness.
790	            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
791	            HandoffSite *site = g_new0(HandoffSite, 1);
792	            site->kind  = HYBRID_HANDOFF_ENTER;
793	            site->vaddr = qemu_plugin_insn_vaddr(insn);
794	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
795	            qemu_plugin_register_vcpu_insn_exec_cb(
796	                insn, on_handoff_boundary, QEMU_PLUGIN_CB_R_REGS, site);
797	            continue;
798	        }
799	
800	        // Marker-trigger mode (default).
801	        // The markers are `slti x0, x0, 0x5A0/0x5A1`, always 32-bit
802	        // (sz==4): SLTI has no compressed form, so the sz!=4 skip is
803	        // exact, not an approximation.
804	        size_t sz = qemu_plugin_insn_size(insn);
805	        if (sz != 4) continue;
806	        uint32_t raw = 0;
807	        if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) != sizeof(raw))
808	            continue;
809	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
810	        if (!hybrid_match_handoff_insn(raw, &kind)) continue;
811	        HandoffSite *site = g_new0(HandoffSite, 1);
812	        site->kind  = kind;
813	        site->vaddr = qemu_plugin_insn_vaddr(insn);
814	        site->size  = (uint32_t) sz;
815	        qemu_plugin_register_vcpu_insn_exec_cb(
816	            insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
817	    }
818	}
