338	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
339	// via an Abstract Command. Halts-and-reads contract: caller must have the
340	// hart in the halted state. Shared by StateDrain (drain at exit), and by
341	// MeasureStartSnapshot (snapshot at K-th retire). If abstractcs.cmderr
342	// goes sticky after the command, the helper clears it and reports 0
343	// rather than blocking the caller -- a missing CSR mirrors as zero
344	// instead of corrupting the adjacent field.
345	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
346	                                     const char* poll_label
347	                                       = "read_register_64")
348	  -> std::optional<uint64_t>
349	{
350	  using RD = ResumeDriver;
351	  bus.write(RD::kCommand,
352	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
353	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
354	  const auto status = bus.read(RD::kAbstractcs);
355	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
356	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
357	    return std::nullopt;
358	  }
359	  const uint64_t lo = bus.read(RD::kData0);
360	  const uint64_t hi = bus.read(RD::kData1);
361	  return lo | (hi << 32);
362	}
363	
364	inline auto read_register_64(DmiBus& bus, uint16_t regno,
365	                             const char* poll_label = "read_register_64")
366	  -> uint64_t
367	{
368	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
369	}
